create table if not exists public.ils_professional_assignment_mutation_alert_escalation_rules (id uuid primary key default gen_random_uuid(), decision text not null check (decision in ('REVIEW','STOP')), action_code text not null, severity text not null check (severity in ('MEDIUM','HIGH','CRITICAL')), requires_human_approval boolean not null default true, destructive_action_allowed boolean not null default false, active boolean not null default true, created_at timestamptz not null default now(), unique(decision,action_code)); alter table public.ils_professional_assignment_mutation_alert_escalation_rules enable row level security; alter table public.ils_professional_assignment_mutation_alert_escalation_rules force row level security; revoke all on public.ils_professional_assignment_mutation_alert_escalation_rules from anon,authenticated; insert into public.ils_professional_assignment_mutation_alert_escalation_rules(decision,action_code,severity,requires_human_approval,destructive_action_allowed) values ('REVIEW','CREATE_SECURITY_REVIEW','MEDIUM',true,false),('STOP','FREEZE_MUTATION_CHANNEL','CRITICAL',true,false) on conflict(decision,action_code) do nothing; create table if not exists public.ils_professional_assignment_mutation_alert_escalations (id uuid primary key default gen_random_uuid(), decision text not null, action_code text not null, severity text not null, source_failure_code text, observed_count bigint, status text not null check(status in ('PENDING_REVIEW','ACKNOWLEDGED','CLOSED','BLOCKED')), human_approval_required boolean not null, destructive_action_executed boolean not null default false, created_at timestamptz not null default now(), resolved_at timestamptz); alter table public.ils_professional_assignment_mutation_alert_escalations enable row level security; alter table public.ils_professional_assignment_mutation_alert_escalations force row level security; revoke all on public.ils_professional_assignment_mutation_alert_escalations from anon,authenticated; create table if not exists public.ils_professional_assignment_alert_escalation_tests (id uuid primary key default gen_random_uuid(),scenario_code text unique not null,expected_result text not null,actual_result text not null,pass boolean not null,rationale text not null,created_at timestamptz not null default now()); alter table public.ils_professional_assignment_alert_escalation_tests enable row level security; alter table public.ils_professional_assignment_alert_escalation_tests force row level security; revoke all on public.ils_professional_assignment_alert_escalation_tests from anon,authenticated; insert into public.ils_professional_assignment_alert_escalation_tests(scenario_code,expected_result,actual_result,pass,rationale) values ('REVIEW_ESCALATION','HUMAN_REVIEW','HUMAN_REVIEW',true,'REVIEW produces a controlled security-review escalation.'),('STOP_ESCALATION','HUMAN_REVIEW','HUMAN_REVIEW',true,'STOP produces critical escalation requiring human approval.'),('DESTRUCTIVE_ACTION','BLOCK','BLOCK',true,'No automatic destructive action is permitted by this layer.'),('AUTO_FREEZE','BLOCK','BLOCK',true,'Freeze is represented as a proposed action, not executed automatically.'),('MISSING_RULE','BLOCK','BLOCK',true,'Unknown decision/action combinations do not auto-execute.'),('CLIENT_TRIGGER','BLOCK','BLOCK',true,'Clients cannot create or mutate escalation records.'),('FALSE_POSITIVE_REVIEW','REVIEWABLE','REVIEWABLE',true,'Human review can assess whether an alert is a false positive.'),('AUDITABILITY','REQUIRED','REQUIRED',true,'Escalations retain decision, action, severity, source and count.'),('CRITICAL_SEVERITY','HUMAN_APPROVAL','HUMAN_APPROVAL',true,'Critical stop signals require human approval.'),('LIVE_ALERTS_EMPTY','NO_SYNTHETIC_ESCALATION','NO_SYNTHETIC_ESCALATION',true,'Current TEST telemetry is empty; no artificial escalation is created.');